#!/usr/bin/env python3
"""
Round 183o (culprits-tiles-more), 5 October 2026.

Adds scripts/ship_noise.py (underwater noise from ships, 2014 to 2020,
Jalkanen et al. 2022, CC BY 4.0) and scripts/whaling_logbooks.py
(WhalingHistory.org logbooks joined to voyages, CC BY 4.0). Each file is
written only if it differs.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, sys

FILES = {'scripts/ship_noise.py': '', 'scripts/whaling_logbooks.py': ''}


def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round183o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round183o_tiles: wrote {path}")
    if not changed:
        print("round183o_tiles: already applied")


if __name__ == "__main__":
    main()
